const expenseCommand=async(operationId,command)=>{const scope=context(),settings=config(),token=await globalThis.OTOTR_FINANCE_AUTH?.getAccessToken?.();if(typeof token!=='string'||token.length<20)throw new Error('AUTH_REQUIRED');const response=await fetch(`${settings.url}/functions/v1/finance-command`,{method:'POST',headers:{apikey:settings.publishableKey,Authorization:`Bearer ${token}`,'Content-Type':'application/json; charset=utf-8','Correlation-Id':crypto.randomUUID(),'X-Client-Info':'ototr-finance-web/0.1'},body:JSON.stringify({operationId,scope,command})}),payload=await response.json().catch(()=>null);if(!response.ok)throw new Error(payload?.error?.message||'Masraf komutu reddedildi.');return payload.data;};
expenseCreateForm?.addEventListener('submit',async event=>{event.preventDefault();let command;try{const scope=context();command={supplierReference:expenseCreateForm.elements.namedItem('supplierReference').value.trim(),feeDefinitionId:expenseCreateForm.elements.namedItem('feeDefinitionId').value.trim(),expenseDate:expenseCreateForm.elements.namedItem('expenseDate').value,currencyCode:expenseCreateForm.elements.namedItem('currencyCode').value.trim().toUpperCase(),netAmount:paymentAmount(expenseCreateForm.elements.namedItem('netAmount').value),taxAmount:String(Number(expenseCreateForm.elements.namedItem('taxAmount').value.replace(',','.')).toFixed(2)),grossAmount:paymentAmount(expenseCreateForm.elements.namedItem('grossAmount').value),contractualBasisReference:expenseCreateForm.elements.namedItem('contractualBasisReference').value.trim(),documentIds:paymentDocuments(expenseCreateForm.elements.namedItem('documentIds').value),targetScopes:[{dealerAccountId:scope.dealerAccountId,branchId:scope.branchId}],note:expenseCreateForm.elements.namedItem('note').value.trim()||null,idempotencyKey:`expense:create:${crypto.randomUUID()}`};if(!UUID.test(command.feeDefinitionId)||Math.abs(Number(command.netAmount)+Number(command.taxAmount)-Number(command.grossAmount))>.00000001)throw new Error('Bedel tanımı UUID olmalı; net + KDV brüt tutara eşit olmalıdır.');}catch(error){expenseCreateState.textContent=error.message;return;}if(!globalThis.confirm('Masraf yansıtma taslağı oluşturulsun mu?'))return;expenseCreateButton.disabled=true;expenseCreateState.textContent='Kapsam, belge ve tutar denklikleri doğrulanıyor…';try{const data=await expenseCommand('createPassThroughExpense',command);expenseCreateForm.dataset.outcome=data.outcome;expenseCreateState.textContent=`Masraf taslağı oluşturuldu · ${data.expenseId}`;globalThis.dispatchEvent(new CustomEvent('ototr:finance-expense-requested',{detail:{expenseId:data.expenseId}}));}catch(error){expenseCreateForm.dataset.outcome='ERROR';expenseCreateState.textContent=error.message==='AUTH_REQUIRED'?'Geçerli kullanıcı oturumu bulunamadı.':error.message;}finally{expenseCreateButton.disabled=false;}});
const expenseActionMap=Object.freeze({DRAFT:['calculateExpenseShares','Payları Hesapla'],CALCULATED:['submitExpenseApproval','Onaya Gönder'],PENDING_APPROVAL:['approveExpense','Bağımsız Onayla'],APPROVED:['postExpense','Muhasebeleştir'],POSTED:['reverseExpense','Ters Kayıt']});
globalThis.addEventListener('ototr:finance-expense-rendered',event=>{selectedExpense=event.detail;const action=expenseActionMap[selectedExpense?.status];expenseActionForm.hidden=!action||document.documentElement.dataset.financeDemo==='synthetic';if(!action)return;const select=expenseActionForm.elements.namedItem('operation'),option=document.createElement('option');option.value=action[0];option.textContent=action[1];select.replaceChildren(option);const calculate=action[0]==='calculateExpenseShares',dated=['postExpense','reverseExpense'].includes(action[0]);document.querySelector('[data-finance-expense-method-wrap]').hidden=!calculate;document.querySelector('[data-finance-expense-rule-wrap]').hidden=!calculate;document.querySelector('[data-finance-expense-date-wrap]').hidden=!dated;document.querySelector('[data-finance-expense-reason-wrap]').hidden=calculate;document.querySelector('[data-finance-expense-note-wrap]').hidden=calculate;expenseActionState.textContent=`${selectedExpense.status} · v${selectedExpense.version} için ${action[1]} işlemi hazır.`;});
expenseActionForm?.addEventListener('submit',async event=>{event.preventDefault();if(!selectedExpense)return;const operationId=expenseActionForm.elements.namedItem('operation').value,base={expenseId:selectedExpense.expenseId,expectedVersion:selectedExpense.version,idempotencyKey:`expense:${operationId}:${selectedExpense.expenseId}:${selectedExpense.version}:${crypto.randomUUID()}`};let command=base;if(operationId==='calculateExpenseShares')command={...base,distributionMethod:expenseActionForm.elements.namedItem('distributionMethod').value,distributionRuleReference:expenseActionForm.elements.namedItem('distributionRuleReference').value.trim()};else{const note=expenseActionForm.elements.namedItem('note').value.trim(),reasonCode=expenseActionForm.elements.namedItem('reasonCode').value;if(!note){expenseActionState.textContent='Karar notu zorunludur.';return;}command={...base,reasonCode,note,...(operationId==='postExpense'?{postingDate:expenseActionForm.elements.namedItem('actionDate').value}:{}),...(operationId==='reverseExpense'?{reversalDate:expenseActionForm.elements.namedItem('actionDate').value,documentIds:[]}:{})};}if(!globalThis.confirm('Seçili masraf yaşam döngüsü işlemi audit izine kaydedilsin mi?'))return;expenseActionButton.disabled=true;expenseActionState.textContent='Yetki, sürüm ve maker-checker denetleniyor…';try{const data=await expenseCommand(operationId,command);expenseActionForm.dataset.outcome=data.outcome;expenseActionState.textContent=`İşlem tamamlandı · ${data.outcome} · v${data.version}`;globalThis.dispatchEvent(new CustomEvent('ototr:finance-expense-requested',{detail:{expenseId:selectedExpense.expenseId}}));}catch(error){expenseActionForm.dataset.outcome='ERROR';expenseActionState.textContent=error.message==='AUTH_REQUIRED'?'Geçerli kullanıcı oturumu bulunamadı.':error.message;}finally{expenseActionButton.disabled=false;}});
